    // Generated by tools/embed-sprite-atlas.mjs — do not edit by hand.
    // Approved Sprite AI reference sprites (D49), base64-embedded; the 54
    // species variants are composed at runtime (HSL recolor + pattern
    // overlay) into one offscreen atlas. No network, no new dependencies.
    const SF_ATLAS_BASE_DATA = [
      // round
      'data:image/png;base64,',
      // block
      'data:image/png;base64,',
      // tall2
      'data:image/png;base64,',
    ]
    // ---- runtime atlas composer (D49) -------------------------------------
    // Composes all 54 species cells at runtime from the three bases: hue-
    // recolor body pixels to the target palette (keeping shading, outline,
    // whites), then overlay pattern darkening (plain / spots / stripes).
    // Deterministic; runs once; falls back to the procedural painter until
    // ready (or forever in non-DOM environments like node --test).
    const SF_ATLAS_CELL = 64
    // 18 = palettes (6) × patterns (3); literal — SF_PALETTES lives in a
    // later fragment and must not be read at module-eval time (TDZ).
    const SF_ATLAS_COLS = 18
    let sfAtlasCanvas = null
    let sfAtlasReady = false
    let sfAtlasStarted = false
    const sfAtlasWaiters = []

    function sfAtlasOnReady(cb) {
      if (sfAtlasReady) cb()
      else sfAtlasWaiters.push(cb)
    }

    function sfRgbToHsl(r, g, b) {
      r /= 255
      g /= 255
      b /= 255
      const max = Math.max(r, g, b)
      const min = Math.min(r, g, b)
      const l = (max + min) / 2
      if (max === min) return [0, 0, l]
      const d = max - min
      const s = l > 0.5 ? d / (2 - max - min) : d / (max + min)
      let h
      if (max === r) h = (g - b) / d + (g < b ? 6 : 0)
      else if (max === g) h = (b - r) / d + 2
      else h = (r - g) / d + 4
      return [(h * 60) % 360, s, l]
    }

    function sfHueDist(a, b) {
      const d = Math.abs(a - b) % 360
      return d > 180 ? 360 - d : d
    }

    /** Body-pixel predicate: saturated mid-luminance pixels near `hue`. */
    function sfBodySelector(ctx, w, h, hue, tol) {
      const img = ctx.getImageData(0, 0, w, h)
      const d = img.data
      const sel = new Uint8Array(w * h)
      for (let i = 0; i < w * h; i += 1) {
        if (d[i * 4 + 3] < 40) continue
        const [hh, ss, ll] = sfRgbToHsl(d[i * 4], d[i * 4 + 1], d[i * 4 + 2])
        if (ss > 0.22 && ll > 0.12 && ll < 0.92 && sfHueDist(hh, hue) <= tol) sel[i] = 1
      }
      return { img, sel }
    }

    function sfAtlasCompose() {
      if (sfAtlasStarted) return
      sfAtlasStarted = true
      if (typeof document === 'undefined' || typeof Image === 'undefined') return
      let loaded = 0
      try {
        const images = SF_ATLAS_BASE_DATA.map((src) => {
          const img = new Image()
          img.onload = () => {
            loaded += 1
            if (loaded === SF_ATLAS_BASE_DATA.length) sfAtlasFinish(images)
          }
          img.src = src
          return img
        })
        void loaded
      } catch (error) {
        console.error('[wait-buddy] sprite atlas init failed', error)
      }
    }

    function sfAtlasFinish(images) {
      try {
        const canvas = document.createElement('canvas')
        canvas.width = SF_PALETTES * SF_PATTERNS * SF_ATLAS_CELL
        canvas.height = 3 * SF_ATLAS_CELL
        const out = canvas.getContext('2d')
        const work = document.createElement('canvas')
        work.width = SF_ATLAS_CELL
        work.height = SF_ATLAS_CELL
        const wctx = work.getContext('2d')
        const tmp = document.createElement('canvas')
        tmp.width = SF_ATLAS_CELL
        tmp.height = SF_ATLAS_CELL
        const tctx = tmp.getContext('2d')
        const rec = document.createElement('canvas')
        rec.width = SF_ATLAS_CELL
        rec.height = SF_ATLAS_CELL
        const rctx = rec.getContext('2d')
        for (let body = 0; body < 3; body += 1) {
          // 1) Draw the base sprite, find its dominant body hue.
          wctx.clearRect(0, 0, SF_ATLAS_CELL, SF_ATLAS_CELL)
          wctx.drawImage(images[body], 0, 0, SF_ATLAS_CELL, SF_ATLAS_CELL)
          let sx = 0
          let sy = 0
          let n = 0
          {
            const probe = wctx.getImageData(0, 0, SF_ATLAS_CELL, SF_ATLAS_CELL)
            const pd = probe.data
            for (let i = 0; i < SF_ATLAS_CELL * SF_ATLAS_CELL; i += 1) {
              if (pd[i * 4 + 3] < 40) continue
              const [hh, ss, ll] = sfRgbToHsl(pd[i * 4], pd[i * 4 + 1], pd[i * 4 + 2])
              if (!(ss > 0.22 && ll > 0.12 && ll < 0.92)) continue
              const rad = (hh * Math.PI) / 180
              sx += Math.cos(rad)
              sy += Math.sin(rad)
              n += 1
            }
          }
          const dominant = n === 0 ? 0 : ((Math.atan2(sy, sx) * 180) / Math.PI + 360) % 360
          // 2) Per palette: recolor body pixels to the target hue/saturation,
          // keeping lightness (shading, outline, whites untouched).
          for (let palette = 0; palette < SF_PALETTES; palette += 1) {
            const target = SF_PALETTE_COLORS[palette]
            tctx.clearRect(0, 0, SF_ATLAS_CELL, SF_ATLAS_CELL)
            tctx.drawImage(work, 0, 0)
            const recol = sfBodySelector(tctx, SF_ATLAS_CELL, SF_ATLAS_CELL, dominant, 50)
            const rd = recol.img.data
            const [th, ts] = sfRgbToHsl(
              parseInt(target.slice(1, 3), 16),
              parseInt(target.slice(3, 5), 16),
              parseInt(target.slice(5, 7), 16),
            )
            for (let i = 0; i < SF_ATLAS_CELL * SF_ATLAS_CELL; i += 1) {
              if (!recol.sel[i]) continue
              const [, , ll] = sfRgbToHsl(rd[i * 4], rd[i * 4 + 1], rd[i * 4 + 2])
              const [rr, rg, rb] = sfHslToRgb(th, ts, ll)
              rd[i * 4] = rr
              rd[i * 4 + 1] = rg
              rd[i * 4 + 2] = rb
            }
            tctx.putImageData(recol.img, 0, 0)
            // Snapshot the recolored sprite for the three pattern passes.
            rctx.clearRect(0, 0, SF_ATLAS_CELL, SF_ATLAS_CELL)
            rctx.drawImage(tmp, 0, 0)
            // 3) Per pattern: plain / spots / stripes (darken body pixels).
            for (let pattern = 0; pattern < SF_PATTERNS; pattern += 1) {
              tctx.clearRect(0, 0, SF_ATLAS_CELL, SF_ATLAS_CELL)
              tctx.drawImage(rec, 0, 0)
              if (pattern !== 0) {
                const pass = sfBodySelector(tctx, SF_ATLAS_CELL, SF_ATLAS_CELL, th, 50)
                const pd = pass.img.data
                const darken = (i) => {
                  pd[i * 4] = Math.round(pd[i * 4] * 0.72)
                  pd[i * 4 + 1] = Math.round(pd[i * 4 + 1] * 0.72)
                  pd[i * 4 + 2] = Math.round(pd[i * 4 + 2] * 0.72)
                }
                if (pattern === 1) {
                  for (const [bx, by] of [[14, 30], [40, 36], [26, 18]]) {
                    for (let dy = 0; dy < 9; dy += 1) {
                      for (let dx = 0; dx < 9; dx += 1) {
                        const x = bx + dx
                        const y = by + dy
                        if (x < SF_ATLAS_CELL && y < SF_ATLAS_CELL) darken(y * SF_ATLAS_CELL + x)
                      }
                    }
                  }
                } else {
                  for (const bx of [20, 30, 40]) {
                    for (let y = 10; y < 56; y += 1) {
                      for (let dx = 0; dx < 4; dx += 1) {
                        if (bx + dx < SF_ATLAS_CELL) darken(y * SF_ATLAS_CELL + bx + dx)
                      }
                    }
                  }
                }
                tctx.putImageData(pass.img, 0, 0)
              }
              out.drawImage(tmp, (palette * SF_PATTERNS + pattern) * SF_ATLAS_CELL, body * SF_ATLAS_CELL)
            }
          }
        }
        sfAtlasCanvas = canvas
        sfAtlasReady = true
        for (const cb of sfAtlasWaiters) cb()
        sfAtlasWaiters.length = 0
      } catch (error) {
        console.error('[wait-buddy] sprite atlas compose failed', error)
      }
    }

    function sfHslToRgb(h, s, l) {
      const c = (1 - Math.abs(2 * l - 1)) * s
      const hp = h / 60
      const x = c * (1 - Math.abs((hp % 2) - 1))
      let r = 0
      let g = 0
      let b = 0
      if (hp < 1) [r, g, b] = [c, x, 0]
      else if (hp < 2) [r, g, b] = [x, c, 0]
      else if (hp < 3) [r, g, b] = [0, c, x]
      else if (hp < 4) [r, g, b] = [0, x, c]
      else if (hp < 5) [r, g, b] = [x, 0, c]
      else [r, g, b] = [c, 0, x]
      const m = l - c / 2
      return [Math.round((r + m) * 255), Math.round((g + m) * 255), Math.round((b + m) * 255)]
    }

    /** Draw the atlas cell for `species` at `size` px. Returns false until
     * the atlas is ready (caller falls back to the procedural painter). */
    function sfAtlasDraw(ctx, species, size) {
      if (!sfAtlasReady) return false
      const body = Math.floor(species / (SF_PALETTES * SF_PATTERNS))
      const palette = Math.floor((species % (SF_PALETTES * SF_PATTERNS)) / SF_PATTERNS)
      const pattern = species % SF_PATTERNS
      const sx = (palette * SF_PATTERNS + pattern) * SF_ATLAS_CELL
      const sy = body * SF_ATLAS_CELL
      ctx.imageSmoothingEnabled = false
      ctx.drawImage(sfAtlasCanvas, sx, sy, SF_ATLAS_CELL, SF_ATLAS_CELL, 0, 0, size, size)
      const rarity = sfRarityOf(species)
      if (rarity === 'very') {
        // Star sparkle, top-right corner.
        const u = size / 16
        ctx.fillStyle = '#ffd23f'
        ctx.fillRect(Math.round(13.5 * u), 0, Math.round(1.5 * u), Math.round(4 * u))
        ctx.fillRect(Math.round(11.5 * u), Math.round(1.5 * u), Math.round(5.5 * u), Math.round(1.5 * u))
        ctx.fillStyle = '#fff6c9'
        ctx.fillRect(Math.round(13.5 * u), Math.round(1.5 * u), Math.round(1.5 * u), Math.round(1.5 * u))
      } else if (rarity === 'rare') {
        const u = size / 16
        ctx.fillStyle = 'rgba(255,255,255,0.85)'
        ctx.fillRect(Math.round(1 * u), Math.round(1 * u), Math.round(1.5 * u), Math.round(1.5 * u))
        ctx.fillRect(Math.round(13 * u), Math.round(6 * u), Math.round(1.2 * u), Math.round(1.2 * u))
      }
      return true
    }

    function sfAtlasEnsure() {
      sfAtlasCompose()
    }
